UPDATE lab.neuron SET cell_type = cell_type || '_renamed'
WHERE cell_type = (SELECT cell_type FROM lab.neuron WHERE cell_type IS NOT NULL
                   GROUP BY cell_type ORDER BY count(*) DESC, cell_type LIMIT 1);
SELECT table_name, operation, old_row->>'cell_type' AS old_type, new_row->>'cell_type' AS new_type
FROM lab.change_log ORDER BY change_id DESC LIMIT 5;
